private fun uniffiCheckContractApiVersion(lib: IntegrityCheckingUniffiLib) {
    // Get the bindings contract version from our ComponentInterface
    val bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    val scaffolding_contract_version = lib.ffi_openbmt_key_ffi_uniffi_contract_version()
    if (bindings_contract_version != scaffolding_contract_version) {
        throw RuntimeException("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    }
}
@Suppress("UNUSED_PARAMETER")
private fun uniffiCheckApiChecksums(lib: IntegrityCheckingUniffiLib) {
    if ((lib.uniffi_openbmt_key_ffi_checksum_func_coin_bits() and 0xFFFF) != 25418) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_func_dice_bits() and 0xFFFF) != 47890) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_func_dice_face_counts() and 0xFFFF) != 14834) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_accept_wallet() and 0xFFFF) != 2032) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_create_approver_only() and 0xFFFF) != 10564) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_create_from_entropy() and 0xFFFF) != 43896) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_device_root() and 0xFFFF) != 34073) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_device_root_words() and 0xFFFF) != 18459) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_key2_public() and 0xFFFF) != 51069) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_openbmt_key_ffi_checksum_method_keyapp_key_words() and 0xFFFF) != 33283) {
