/**
 * The person's decision on a line (AS-30).
 */
sealed class Decision {
    
    /**
     * Approve the line.
     */
    object Approve : Decision()
    
    
    /**
     * Decline it, with a reason of 1 to 160 bytes.
     */
    data class Decline(
        /**
         * The reason.
         */
        val `reason`: kotlin.String) : Decision()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDecision : FfiConverterRustBuffer<Decision>{
    override fun read(buf: ByteBuffer): Decision {
        return when(buf.getInt()) {
            1 -> Decision.Approve
            2 -> Decision.Decline(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Decision): ULong = when(value) {
        is Decision.Approve -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Decision.Decline -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: Decision, buf: ByteBuffer) {
        when(value) {
            is Decision.Approve -> {
                buf.putInt(1)
                Unit
            }
            is Decision.Decline -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





