/**
 * Where key 2's randomness comes from (`docs/DESIGN.md` §5.4). With every
 * source but `Platform` nothing else is mixed in, so the same throws give
 * the same words in another tool.
 */
sealed class EntropySource {
    
    /**
     * "Let this device make it": 32 bytes from the platform's random
     * source, 24 words.
     */
    object Platform : EntropySource()
    
    
    /**
     * Dice, hashed: at least 99 rolls written as the digits 1 to 6; 24
     * words from their SHA-256 hash.
     */
    data class DiceHashed(
        /**
         * The digits, in the order rolled.
         */
        val `rolls`: kotlin.String) : EntropySource()
        
    {
        

        companion object
    }
    
    /**
     * Coin, skew-corrected (von Neumann).
     */
    data class CoinFlips(
        /**
         * `true` for heads, in the order flipped.
         */
        val `heads`: List<kotlin.Boolean>, 
        /**
         * 12 or 24 words.
         */
        val `words`: org.openbmt.key.ffi.KeyWordCount) : EntropySource()
        
    {
        

        companion object
    }
    
    /**
     * Dice, skew-corrected (von Neumann).
     */
    data class DiceSkewCorrected(
        /**
         * The digits 1 to 6, in the order rolled.
         */
        val `rolls`: kotlin.String, 
        /**
         * 12 or 24 words.
         */
        val `words`: org.openbmt.key.ffi.KeyWordCount) : EntropySource()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeEntropySource : FfiConverterRustBuffer<EntropySource>{
    override fun read(buf: ByteBuffer): EntropySource {
        return when(buf.getInt()) {
            1 -> EntropySource.Platform
            2 -> EntropySource.DiceHashed(
                FfiConverterString.read(buf),
                )
            3 -> EntropySource.CoinFlips(
                FfiConverterSequenceBoolean.read(buf),
                FfiConverterTypeKeyWordCount.read(buf),
                )
            4 -> EntropySource.DiceSkewCorrected(
                FfiConverterString.read(buf),
                FfiConverterTypeKeyWordCount.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EntropySource): ULong = when(value) {
        is EntropySource.Platform -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is EntropySource.DiceHashed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`rolls`)
            )
        }
        is EntropySource.CoinFlips -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceBoolean.allocationSize(value.`heads`)
                + FfiConverterTypeKeyWordCount.allocationSize(value.`words`)
            )
        }
        is EntropySource.DiceSkewCorrected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`rolls`)
                + FfiConverterTypeKeyWordCount.allocationSize(value.`words`)
            )
        }
    }

    override fun write(value: EntropySource, buf: ByteBuffer) {
        when(value) {
            is EntropySource.Platform -> {
                buf.putInt(1)
                Unit
            }
            is EntropySource.DiceHashed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`rolls`, buf)
                Unit
            }
            is EntropySource.CoinFlips -> {
                buf.putInt(3)
                FfiConverterSequenceBoolean.write(value.`heads`, buf)
                FfiConverterTypeKeyWordCount.write(value.`words`, buf)
                Unit
            }
            is EntropySource.DiceSkewCorrected -> {
                buf.putInt(4)
                FfiConverterString.write(value.`rolls`, buf)
                FfiConverterTypeKeyWordCount.write(value.`words`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Why a call did not do what was asked. Every variant carries the ID of
 * the rule that refused (for example `AS-20` or `SR-30`) when the refusal
 * comes from one of the rule crates, and the crate's own text, which says
 * why and what to do next where the underlying error has it.
 */
sealed class KeyException: kotlin.Exception() {
    
    /**
     * A rule in one of the existing crates refused. `rule` is its ID, or
     * the name of the check when the error has no ID.
     */
    class Refused(
        
        /**
         * The rule's ID.
         */
        val `rule`: kotlin.String, 
        
        /**
         * The refusal, as the rule crate words it.
         */
        val `text`: kotlin.String
        ) : KeyException() {
        override val message
            get() = "rule=${ `rule` }, text=${ `text` }"
    }
    
    /**
     * The storage callback failed, or the stored bytes cannot be read.
     * Nothing was changed.
     */
    class Store(
        
        /**
         * `AS-34` for a failed store, `OBM7` for unreadable bytes.
         */
        val `rule`: kotlin.String, 
        
        /**
         * What went wrong.
         */
        val `text`: kotlin.String
        ) : KeyException() {
        override val message
            get() = "rule=${ `rule` }, text=${ `text` }"
    }
    
    /**
     * The call is not possible in the state the Key app is in.
     */
    class State(
        
        /**
         * A short name of the state rule.
         */
        val `rule`: kotlin.String, 
        
        /**
         * What to do instead.
         */
        val `text`: kotlin.String
        ) : KeyException() {
        override val message
            get() = "rule=${ `rule` }, text=${ `text` }"
    }
    
    /**
     * A panic was caught. The object is poisoned: every later call
     * returns this error until the app opens the object again.
     */
    class Internal(
        
        /**
         * Always `internal`.
         */
        val `rule`: kotlin.String, 
        
        /**
         * What was caught.
         */
        val `text`: kotlin.String
        ) : KeyException() {
        override val message
            get() = "rule=${ `rule` }, text=${ `text` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<KeyException> {
        override fun lift(error_buf: RustBuffer.ByValue): KeyException = FfiConverterTypeKeyError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeKeyError : FfiConverterRustBuffer<KeyException> {
    override fun read(buf: ByteBuffer): KeyException {
        

        return when(buf.getInt()) {
            1 -> KeyException.Refused(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> KeyException.Store(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> KeyException.State(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> KeyException.Internal(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KeyException): ULong {
        return when(value) {
            is KeyException.Refused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`rule`)
                + FfiConverterString.allocationSize(value.`text`)
            )
            is KeyException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`rule`)
                + FfiConverterString.allocationSize(value.`text`)
            )
            is KeyException.State -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`rule`)
                + FfiConverterString.allocationSize(value.`text`)
            )
            is KeyException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`rule`)
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
    }

    override fun write(value: KeyException, buf: ByteBuffer) {
        when(value) {
            is KeyException.Refused -> {
                buf.putInt(1)
                FfiConverterString.write(value.`rule`, buf)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is KeyException.Store -> {
                buf.putInt(2)
                FfiConverterString.write(value.`rule`, buf)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is KeyException.State -> {
                buf.putInt(3)
                FfiConverterString.write(value.`rule`, buf)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is KeyException.Internal -> {
                buf.putInt(4)
                FfiConverterString.write(value.`rule`, buf)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



