/**
 * Where the Key app is in its setup (`docs/DESIGN.md` §2.1).
 */
sealed class SetupState {
    
    /**
     * Nothing is stored.
     */
    object Empty : SetupState()
    
    
    /**
     * The identity (and key 2, if this device holds it) is stored; no
     * wallet has been accepted yet.
     */
    data class HasIdentity(
        /**
         * Key 2 is on this device.
         */
        val `holdsKey2`: kotlin.Boolean, 
        /**
         * The words of the key just made have not been taken yet with
         * `key_words`. They are not stored and cannot be shown again.
         */
        val `wordsWaiting`: kotlin.Boolean) : SetupState()
        
    {
        

        companion object
    }
    
    /**
     * The wallet and the owner root are pinned. Sessions can be opened.
     */
    data class Ready(
        /**
         * Key 2 is on this device.
         */
        val `holdsKey2`: kotlin.Boolean) : SetupState()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSetupState : FfiConverterRustBuffer<SetupState>{
    override fun read(buf: ByteBuffer): SetupState {
        return when(buf.getInt()) {
            1 -> SetupState.Empty
            2 -> SetupState.HasIdentity(
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                )
            3 -> SetupState.Ready(
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SetupState): ULong = when(value) {
        is SetupState.Empty -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is SetupState.HasIdentity -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`holdsKey2`)
                + FfiConverterBoolean.allocationSize(value.`wordsWaiting`)
            )
        }
        is SetupState.Ready -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`holdsKey2`)
            )
        }
    }

    override fun write(value: SetupState, buf: ByteBuffer) {
        when(value) {
            is SetupState.Empty -> {
                buf.putInt(1)
                Unit
            }
            is SetupState.HasIdentity -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`holdsKey2`, buf)
                FfiConverterBoolean.write(value.`wordsWaiting`, buf)
                Unit
            }
            is SetupState.Ready -> {
                buf.putInt(3)
                FfiConverterBoolean.write(value.`holdsKey2`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * The error of a [`KeyStore`](crate::KeyStore) call, raised by the app's
 * own code.
 */
sealed class StoreException: kotlin.Exception() {
    
    /**
     * The platform call failed. Nothing was stored.
     */
    class Failed(
        
        /**
         * What the platform said.
         */
        val `text`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "text=${ `text` }"
    }
    
    /**
     * The app's callback threw something it did not declare.
     */
    class Unexpected(
        
        /**
         * What was thrown.
         */
        val `text`: kotlin.String
        ) : StoreException() {
        override val message
            get() = "text=${ `text` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<StoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): StoreException = FfiConverterTypeStoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeStoreError : FfiConverterRustBuffer<StoreException> {
    override fun read(buf: ByteBuffer): StoreException {
        

        return when(buf.getInt()) {
